"""Freeze lesson text and activity inputs before editing learner HTML."""
from pathlib import Path
import html,json
ROOT=Path(__file__).resolve().parents[1];F=ROOT/'_source/fragments';F.mkdir(parents=True,exist_ok=True)
M=ROOT/'assets/materials'
pages={}
def p(t):return '<p class="body-text">'+t+'</p>'
def section(id,title,text):return f'<section class="lesson-section" id="{id}"><h2 class="section-heading">{title}</h2>{text}</section>'
def steps(items):return '<ol class="body-text">'+''.join('<li>'+t+'</li>' for t in items)+'</ol>'
def link(name,label):return f'<a href="../assets/materials/{name}" download>{label}</a>'
def tool(name,label):return f'<a href="../assets/tools/{name}" target="_blank" rel="noopener">{label}</a>'
def answer(t):return '<details><summary>完成預判後核對答案</summary>'+p(t)+'</details>'
def prompt(id,text):
    (M/(id+'.txt')).write_text(text+'\n')
    return p(link(id+'.txt','下載完整生成指令 TXT'))+f'<pre class="result-box" id="{id}">{html.escape(text)}</pre><button class="copy-btn" type="button" data-copy="{id}">複製完整指令</button><span role="status" data-copy-status="{id}"></span>'
def save_hint(name):return p(f'將輸出保存為 <strong>{name}</strong>；只複製從 &lt;!DOCTYPE html&gt; 到 &lt;/html&gt; 的完整內容。Windows 記事本另存新檔時選「所有檔案」與 UTF-8；Mac TextEdit 先選「格式→製作純文字」，關閉自動補 .txt。檔名若成為 .html.txt，顯示副檔名後移除最後的 .txt。雙擊檔案應開成工具；看到程式文字時先檢查副檔名。')
def add(file,title,tagline,outcomes,parts):
    content='\n'.join(section(f'core-{i+1}',t,b) for i,(t,b) in enumerate(parts))
    pages[file]={'title':title,'tagline':tagline,'outcomes':outcomes,'fragment':file.replace('/','-').replace('.html','.fragment')}
    (F/pages[file]['fragment']).write_text(content+'\n')

add('part1/CH1-1.html','從一個工作需求開始','先看工具如何工作，再確認帳號與操作起點。今天會留下能核對、能保存、能再次使用的成果。',['分辨用 AI 生成工具與工具執行時呼叫 AI','完成帳號與資料夾準備'],[
('先看一個完整結果',p('活動會議需要讓每位發言者知道剩餘時間。打開 '+tool('timer-reference.html','計時器參考品')+'，填 10 秒，按開始；暫停時數字停止，重設後回到設定值。這個工具只需要固定規則，生成後可以離線執行。')+p('稍後的會議逐字稿則需要理解「取消」與「只是提議」，才會在執行時使用 AI。前段先練習規則明確的工具，後段再加入語意判斷。')),
('準備帳號與保存位置',steps(['以電腦瀏覽器打開 <a href="https://aistudio.google.com/" target="_blank" rel="noopener">Google AI Studio</a>，登入可使用該服務的 Google 帳號。看到登入頁就先完成登入；遇到組織限制請改用講師核准的帳號，不要一直重送。','找到可输入訊息並執行的 Chat／對話頁。本課前段要取得一份完整 HTML 文字；先不進 Build。按鈕位置以帳號畫面為準，找不到時用 <a href="https://ai.google.dev/gemini-api/docs/ai-studio-quickstart" target="_blank" rel="noopener">官方對話說明</a>確認。','在電腦建立「AI工作工具」資料夾；開啟記事本或純文字 TextEdit，建立 notes.txt，寫下資料夾位置。','下載 '+link('requirements-template.txt','需求單')+' 與 '+link('acceptance-template.csv','驗收紀錄')+'。看到兩個實際檔案才算準備完成。'])) ,
('今天的路線與卡關處理',p('必修只做計時器暖身、預算、KPI 與 AI 交辦，再保存與獨立改造。其餘圖表、指令工具與部署依工作需要選修。每個工具都用已知答案的資料查核，不以外觀或完成速度評分。')+p('帳號暫時不可用時，先使用參考品完成需求判斷與核對；在驗收表標「生成待完成」。生成失敗不代表需求一定寫錯，也可能是環境、額度或輸出問題。回到受影響步驟修復後重測，不要清空已完成資料。'))])

add('part1/CH1-2.html','把需求寫成可核對的規格','沿用計時器，追加「會議主題」需求；讓 AI 知道你要看到什麼結果。',['寫清輸入、規則、例外與輸出','為一項修改訂出可觀察的通過標準'],[
('從用途推導四個必要資訊',p('角色與任務有助於交代背景；要讓工具算對，還需要資料與規則。計時器的輸入是秒數，規則是每秒減一；暫停後停止減少，重設後回到設定值。空值或負數不能開始。輸出是剩餘秒數及時間到提示。')+p('先打開需求單，填入上述資訊。再增加會議主題欄，規則寫「輸入主題後顯示在剩餘時間旁，修改主題不會重設倒數」。你需要判斷的是改動是否符合工作使用方式。')),
('同步修改：先預判再寫指令',steps(['在 '+tool('timer-reference.html','參考品')+' 填「活動籌備」，按開始。觀察倒數期間修改主題會如何影響數字。','在需求單寫一個測試：10 秒開始後改主題，數字應繼續倒數，暫停後才停止。','把需求改寫成「增加主題欄，倒數期間只改主題文字，不重設剩餘秒數；保留開始、暫停與重設功能」。','下一站貼完整指令生成工具，再跑這個測試。不要先做一個指令組合器來完成這項任務。'])) ,
('用缺口查核取代刷分',p('核對需求是否缺少輸入、規則、例外或輸出。關鍵字命中分數不能證明工具品質；真正的回饋是：哪一筆測試沒通過、觀察到什麼、修正後是否成功。指令組合台與健診器留在選修，當你需要整理需求時再使用。')+answer('若修改主題讓倒數回到 10 秒，便沒有通過「修改主題不重設倒數」；應回修這項行為，不必更換整套工具。'))])

timer_prompt='''請製作單一完整 HTML 的會議倒數計時器。所有 CSS 與 JavaScript 寫在同一檔，不用外部套件、API 或 Build 專案。
使用繁體中文，介面清楚且手機可用。輸入會議主題與正整數秒數；有開始、暫停、重設按鈕。開始後每秒減一，重複按開始不能加速；暫停停止減少；重設回到設定值；修改主題只改顯示，不重設倒數。倒數歸零顯示時間到，不得負數。空值、0、負數或非整數應阻止開始並提示。
請只輸出從 <!DOCTYPE html> 到 </html> 的完整程式文字，不能省略，不能只給差異。測試：10 秒開始，約3秒後暫停應剩約7秒；等待2秒不變；重設回10。'''
add('part1/CH1-3.html','生成、保存並重開第一個工具','把上一站的規格交給 AI，自己核對倒數與存檔結果。',['保存可重開的計時器','測試一項正常行為與一項例外'],[
('貼完整指令，取得一個檔案',p('在 AI Studio 的對話輸入框貼下方指令，按畫面的執行／送出。等待輸出完整結束；本課不保證固定生成時間。若回覆只有解釋，追加「請輸出完整单檔 HTML，不要只解釋」。若出現多檔框架專案，回對話頁重送單檔要求。')+prompt('prompt-timer',timer_prompt)),
('存檔與第一次重開',save_hint('meeting-timer.html')+steps(['雙擊 meeting-timer.html。先輸入 10 秒與會議主題，確認有三個操作按鈕。','測開始、暫停、重設及主題修改；瀏覽器排程可能略有時間差，不要求肉眼精確毫秒。','輸入空值或負數，應看到提示且不能開始。再填 10 秒恢復正常。','關閉分頁，從資料夾重新雙擊檔案；應能再次倒數。把實測結果填入驗收表，保存完整指令。'])) ,
('按現象修復後重測',p('若多按開始會加速，回原對話說：「重複按開始造成多個倒數；請修成同時只有一個倒數，保留其他功能，輸出完整 HTML。」存成 meeting-timer-v2.html，保留 v1，再跑同一組測試。')+p('若無法生成，下載 '+tool('timer-reference.html','離線參考品')+' 繼續查核，並在驗收表標記參考品／生成待完成。第一次成功要有存檔與測試證據，與講師示範分開記錄。'))])

add('part2/CH2-1.html','先算清楚：預算差異與剩餘額','活動承辦人需要知道花了多少、比估算多多少，以及還有多少核定額度。',['區分估算、實支與核定預算','手動核對一組完整工作數字'],[
('拿到資料再決定欄位',p('下載 '+link('budget-normal.csv','四項活動費用 CSV')+'。item 是項目，quantity 是數量，unit_price 是單價，actual 是這一項的實支總額，note 是原因。所有金額已包含必要費用，本案不另外加稅。核定預算在工具填 30,000 元。')+p('講師 4×2,500＝10,000；場地 1×8,000＝8,000；餐點 40×150＝6,000；印刷 40×50＝2,000。估算合計 26,000。逐項實支為 10,500、8,500、6,500、2,300，合計 27,800。')),
('兩個差值回答不同問題',p('「實支－估算」回答增加多少費用：27,800－26,000＝1,800。「核定－實支」回答還剩多少額度：30,000－27,800＝2,200。兩個數字不能都叫剩餘預算。')+p('打開 '+tool('budget-reference.html','預算完成品')+'，先預判核定改成 27,000 的結果，再修改。實支與估算沒有改變，所以差異仍是 1,800；餘額變成 -800，表示超支。工具應顯示超支，不用將負數截成零。')),
('下一站由你做工具',p('把欄位、兩個公式與例外寫入需求單。下一站生成相同工作用途的工具，改餐點人數並測空值。核對前先不要調整風格；裝飾不會修正公式。參考品可下載備援，但完成證據要標明誰生成、使用哪份資料。'))])

budget_prompt='''請製作活動預算與核銷差異表，單一完整 HTML，CSS/JavaScript 全內嵌，不用外部套件、不呼叫 AI/API。
欄位：項目、數量（非負整數）、單價、實支總額、備註；可新增刪除明細。核定預算獨立輸入。空值、負數、非有限數值應阻止計算與匯出，不能默認零；金額最多兩位小數。所有費用已包含必要費用，不另外加稅。
逐項估算=數量×單價；估算合計加總逐項；实支合計加總實支總額；較估算差異=實支合計-估算合計；核定餘額=核定-實支合計，負餘額顯示超支。金額以分為單位計算避免小數累加誤差。
預設：講師4×2500實支10500（交通費）；場地1×8000實支8500（延長）；餐點40×150實支6500（配送）；印刷40×50實支2300（加印）；核定30000。
支援以 item,quantity,unit_price,actual,note 欄位貼上 CSV 匯入（中文與引號可用）；錯誤資料不覆蓋原資料。下載明細 CSV 與總額；列印／另存 PDF；本機保存；備份 JSON 並可還原，還原先驗證再覆蓋。手機表格在自己的容器內橫向滑動。
預期：估算26000、實支27800、差異1800、餘額2200。只輸出 <!DOCTYPE html> 到 </html> 的完整內容，不省略。'''.replace('实','實')
add('part2/PRAC2-1.html','做出能查核的活動預算表','沿用四項活動資料，改一個條件，找出差異並完成可交付報告。',['生成與核對兩個預算公式','處理缺值並輸出 CSV／PDF'],[
('生成與載入標準資料',prompt('prompt-budget',budget_prompt)+save_hint('activity-budget.html')+p('打開自製工具，核定填 30,000。若預設資料缺漏，把 '+link('budget-normal.csv','標準資料')+' 以純文字打開，貼入 CSV 匯入區。核對 26,000／27,800／1,800／2,200 四個值；來源檔 actual 是逐項實支總額，不再乘數量。')),
('同步修改：餐點改為 45 人',steps(['先預判哪個值會改。只把餐點數量改 45，單價與實支暫時不動。','重新核對：估算、實支、差異與餘額。告訴同桌為什麼餘額沒有跟著改。','核定改 27,000，應显示超支；改回 30,000。把每次實測寫到驗收表。'])+answer('餐點估算 6,750；總估算 26,750；實支仍 27,800；差異 1,050；餘額仍 2,200。核定 27,000 時餘額 -800。')),
('例外與修復：未知不能當零',p('下載 '+link('budget-invalid.csv','缺值／負數資料')+'，先不要覆蓋已完成資料。匯入應拒絕並保留目前明細；或直接清空餐點數量，工具應停止總額與匯出。填回 45 後應恢復。')+p('若空值被當零，回原對話貼：「餐點數量空白時仍有總額；請將空值與負值判為錯誤，停止計算與匯出，修正後恢復，輸出完整 HTML。」保存 v2 並重跑正常與空值測試。只修改提示而仍顯示舊總額不算修好。')),
('交付並確認可再次更新',steps(['下載明細 CSV，用試算表打開，確認中文、逐項估算與總額。','選列印，目的地選「另存 PDF」，保存 activity-budget-report.pdf，開檔核對四個總額與備註。','下載 JSON 備份，關閉工具後重開；修改一個備註，重新輸出。若換電腦，以 JSON 還原並核對。','保存完整指令與驗收紀錄；工具資料只存在目前瀏覽器時，必須交付資料備份。'])+p('卡關時可用 '+tool('budget-reference.html','參考預算工具')+' 比對公式、匯入與輸出，記錄哪些步驟仍是待完成。'))])

kpi_prompt='''請製作部門 KPI 月報，單一完整 HTML，CSS/JavaScript 全內嵌、不用外部套件，不呼叫 AI。
每個指標有 metric 指標、unit 單位、direction（higher 越大越好／lower 越小越好）、target 目標、actual 實際、previous 上期、period 期間、source 來源。可新增編輯；CSV 匯入要驗證欄位、引號及非負數值。缺值不當零。
higher:actual>=target 達標；lower:actual<=target 達標。達標文字必須遵照方向，不用同一個 actual/target 百分比當所有指標的分數。圖表顯示目標與實際的比較，補文字、單位和方向，不能只靠顏色。上期變化=(actual-previous)/previous×100%；previous=0 或缺值時顯示不可計算。target=0 仍可判斷達標，但不計達成率。錯誤率以1代表1%，不可變成100%。
預設：受理件數 件 higher 目標100 實際120 上期90；處理時間 天 lower 目標3 實際5 上期4；錯誤率 % lower 目標2 實際1 上期1.5。期間2026-09，來源分別案件台帳、結案台帳、複核紀錄。
下載月報 CSV、列印另存 PDF、本機保存、JSON備份還原。缺數值可交付但須顯示待確認；指標、單位、期間或來源缺漏須阻止匯出。數字只說結果，不生成沒有證據的原因。手機表格容器可橫向滑動。只輸出完整 HTML 不省略。'''
add('part3/PRAC3-3.html','用 KPI 月報做一項工作判斷','同樣的比值，會因指標方向產生不同結論；先核對數字再選圖表。',['正確判斷三種指標與缺值','交付有期間、來源與例外說明的月報'],[
('先判斷，再生成月報',p('下載 '+link('kpi-normal.csv','三項 KPI 資料')+'。件數越大越好；處理時間与錯誤率越小越好。先寫下 120 件、5 天、1% 各自是否達標，再看 '+tool('kpi-reference.html','月報參考品')+'。')+answer('受理件數 120≥100，已達標；處理時間 5>3，未達標；錯誤率 1≤2，已達標。處理時間變長 25%，不能解讀成績效更好。件數較上期 +33.3%；錯誤率較上期 -33.3%。')+prompt('prompt-kpi',kpi_prompt)),
('同步操作：讓資料可以更新',save_hint('department-kpi.html')+steps(['生成後核對三個達標狀態與上期變化，檢查圖表單位。','將處理時間由 5 改成 2 天，先預判再操作；應改為已達標，較上期 -50%。','寫一段工作判讀：「本期處理時間未達標，需要調查流程卡點」，指出資料來源。沒有原因證據時不要寫人力不足。','保存 CSV 與 PDF，再用原始資料恢復，確定可更新而不是固定圖片。'])) ,
('例外：基期零、缺值與零目標',p('匯入 '+link('kpi-exceptions.csv','例外資料')+'。新增服務上期為 0，本期 12：可判達標，但變化百分比不可計算。回覆時間實際缺漏：狀態待確認。錯誤率目標 0、實際 0：達標，不算 actual/target。')+p('若未知被顯示為 0%，用這筆資料回原對話要求修復：「空值保持未知；基期為零顯示不可計算；不要以達成率統一判所有指標。」保存 v2，再測正常三項與例外三項。這次新增的判斷是方向與缺值，無須再做雷達、甘特與漏斗才能進下一站。'))])

add('part6/CH6-1.html','會議交辦：先分辨決議與提議','從固定公式轉向文字判斷，核對原文後才把 AI 結果交給同事。',['分辨有效交辦、提議、取消與未知','知道何時轉入 Build 與何時需要人工確認'],[
('用原文建立欄位答案',p('下載 '+link('meeting-a.txt','完整逐字稿 A')+'，先圈出確定要做的事項。林承諾確認場地；陳承諾餐點詢價但未定期限；直播只是提議；邀請寄送已取消。最後兩者都不應成為有效待辦。')+p('有效交辦的欄位是任務、責任人、期限、狀態、來源原文、待確認原因與人工確認。未出現的期限應保留未知，不能因「明天」出現在取消句中就補給其他任務。')+answer('兩項有效交辦：林／確認場地／2026-10-09；陳／餐點詢價／期限待確認。未人工核對前，confirmed 都是 false。')),
('這次轉入 Build',p('前段 Chat 生成的單檔工具，執行時只跑固定規則；這次要把逐字稿送入模型整理。在 AI Studio 找到 <a href="https://aistudio.google.com/apps" target="_blank" rel="noopener">Build</a>，建立網頁應用，貼下一站的生成描述；待程式生成後，在預覽內的逐字稿欄貼 A。描述框與應用輸入框是兩個不同位置。')+p('必修只測 Build 預覽與結果保存，不需要公開網址。不把下載的專案 ZIP 當成可雙擊 HTML。依 <a href="https://ai.google.dev/gemini-api/docs/aistudio-build-mode" target="_blank" rel="noopener">官方 Build 說明</a>，AI 呼叫使用伺服器端金鑰；本課指令會要求金鑰留在伺服器，不貼到瀏覽器或逐字稿欄。平台額度與帳號限制依當時畫面確認，不能保證全部免費。')),
('先確認工作結果，再處理發布',p('AI 輸出是草稿。人工核對來源、期限與最後決議後，才可勾選確認。若原文沒有資料，詢問會議主持人，或標待確認；不讓工具自動寄信或寫入日曆。下一站會用 B 測試責任人變更、已完成與取消。公開發布、React／SDK 與 GitHub 部署都在選修。'))])

meeting_prompt='''製作繁體中文的會議交辦確認表網頁應用，在 AI Studio Build 預覽可用。
使用者在應用的逐字稿輸入框貼文字，按整理。伺服器呼叫 Gemini 進行語意分析，不得以正則或關鍵字命中冒充模型。金鑰僅放伺服器端環境，不送到瀏覽器。輸出 JSON 並驗證欄位與語意；錯誤時保留原文和上一版已確認資料，清楚顯示失敗，允許重試。
有效待辦只收本次最後明確成立且未完成的交辦；提議、取消、已完成另列排除清單與理由。重複回報合併；後續更新責任人與期限取代舊值，但保留更新原文。
欄位：task_id、task、owner（未知null）、due_date（YYYY-MM-DD或未知null）、status、source_text（逐字引用）、uncertain_reason、confirmed（預設false）。不要猜期限或責任人。缺任務、原文或無法解析的日期須標為待確認，不默認成功。使用者可修改欄位，查看原文，勾選人工確認；匯出CSV標明確認狀態，不得自動寄送。
空白输入應停止整理；模型或網路失敗顯示失敗與重試，不輸出假結果。支援下載逐字稿、結果 JSON、交辦 CSV；提供重新匯入 JSON 功能，驗證後才覆蓋。確認與未知不等同，責任人/期限未定的資料即使已核對仍保留待確認原因。
畫面提供標準逐字稿按鈕但清楚標示示例；不要把預設範例硬編碼當作新文字的分析結果。使用可讀表格與手機表格容器。'''.replace('输入','輸入')
add('part6/PRAC6-1.html','生成並驗證 AI 會議交辦表','用兩份逐字稿測語意與修復；完成核對後保存結果，無須先發布。',['實測兩份逐字稿與欄位答案','修正誤提取、保存原文與確認結果'],[
('Build 描述與第一筆輸入',prompt('prompt-meeting',meeting_prompt)+steps(['在 AI Studio Build 描述框貼完整指令，選網頁應用並開始生成。看到預覽後，確認有逐字稿輸入與整理按鈕。','下載 '+link('meeting-a.txt','逐字稿 A')+'，開啟 TXT，全選文字貼到「應用預覽內」的逐字稿輸入框，按整理。','核對是否有兩項有效交辦。若只完成描述表單但未貼逐字稿執行，這一步尚未完成。','查看林與陳的原文，確認林的期限與陳的未知；直播與取消邀請不能在有效待辦中。核對後才勾人工確認。'])) ,
('新資料 B：需要重新判斷',p('下載 '+link('meeting-b.txt','逐字稿 B')+'。先寫出最後有效的任務、責任人、期限及排除原因，再貼到同一應用整理。這次會變更原有負責人與期限，不能只複製 A 的答案。')+answer('三項有效待辦：陳／餐點詢價／2026-10-12；整理報名名單／負責人與期限待確認；王／海報／2026-10-13。場地已完成可放歷史，問卷只是提議，邀請仍取消。海報的林／2026-10-10 已被更新取代。')+p('完整欄位見 '+link('reference-answers.json','答案 JSON')+' 或 '+tool('meeting-reference.html','可閱讀的答案頁')+'。措辭可以不同，但任務意思、原文、責任人、日期與未知狀態都要符合。')),
('修復並重跑，不能改成固定答案',p('若邀請被列為待辦，在 Build 原對話回報：「A 的取消邀請被誤列；請先辨識最後決議，提議、取消與完成另列排除理由，保留原文，不硬編碼 A 的答案。」再跑 A 與 B，記下修正結果。若 B 海報還是林，回修最後更新取代舊值的規則。')+p('空白輸入應停止；呼叫失敗應顯示失敗與重試，不能輸出空表當成功。權限、額度或連線限制時，保存逐字稿與畫面，把 AI 生成／呼叫記為待完成；使用答案頁練查核，不宣稱模型成功。')),
('把交辦表交付给人',steps(['下載交辦 CSV、結果 JSON 與逐字稿。CSV 中應看得到待確認原因與人工確認狀態。','重新載入 JSON，核對資料沒有少列；匯入無效 JSON 應保留原資料並提示。','在 AI Studio 保存專案，記錄可再次開啟的專案位置／網址；重開專案預覽，用 A 再測一次。','記錄 B 的三項結果與排除項，保存完整生成描述與修復指令。下一站整理所有成果；公開 Share／Publish 不屬於此步通過條件。']))])

add('part4/CH4-1.html','保存成果，確認下次真的能用','整理前面已完成的檔案與 AI 專案，從工作資料重新產出一次結果。',['區分單檔工具與 AI 專案保存方式','交付成品、資料、指令與使用說明'],[
('整理交付包，不再建一個保存工具',p('在 AI工作工具 資料夾建立「工具」「資料」「指令」「報告」「驗收」五個子資料夾。把 meeting-timer.html、activity-budget.html、department-kpi.html 放工具；CSV、逐字稿與 JSON 放資料；生成與修復指令放指令；PDF 與交辦 CSV 放報告。')+p('AI 交辦需要 Build 專案與伺服器模型呼叫；在使用說明寫下專案位置、登入條件與如何重新測試。匯出的 ZIP 只是專案備份，不等同可直接雙擊的 HTML。')),
('關閉、重開、更新、再輸出',steps(['關閉單檔工具分頁，從資料夾雙擊 HTML；核對原資料或匯入備份。若本機資料未保留，還原 JSON；無效備份不能覆蓋正常資料。','預算改一個備註再輸出；KPI 改一個實際值，預判狀態後輸出月報。打開新 CSV／PDF，確認內容更新。','重新開啟 AI Studio 專案，貼 A 測一次；從資料夾開交辦 CSV，確認原文、未知與確認欄都在。','打開驗收表，標明實際生成、使用參考品、通過及待完成，不用閱讀捲動進度代替工作成果。'])) ,
('使用說明與修復入口',p('新增 README.txt，寫「工具用途、打開方式、資料來源、正常答案、未知如何處理、備份位置、失敗回到哪個步驟」。例如預算公式錯回預算生成對話；副檔名錯回存檔；AI 整理錯回 Build 規則並重測 A/B。不要在修復時刪掉所有原資料。')+p('本機文件含資料時，只交給需要使用的人。公開網址、多人同步與背景通知另學；保存好檔案、可重新查核與更新，已能支持下次工作。'))])

add('part4/PRAC4-3.html','獨立改造與成果交付','選一個工作需求，自己改規格、預判、驗證與修復，留下可再次使用的成果。',['以新資料或規則獨立改造工具','交付可重開的成品與再測證據'],[
('選一個改造，不以工具數量評分',p('預設選預算遷移：下載 '+link('budget-transfer.csv','新的活動資料')+'，核定改 25,000；沿用已做預算工具，先手算再匯入。也可選 KPI 新指標、AI 交辦新匿名逐字稿，或 '+ '<a href="../part5/PRAC5-12.html">行政案件追蹤選項</a>。只有選到需要的功能才追加，不必所有人做完整案件板。')+p('用需求單寫「工作用途、改了什麼、預期變化、例外、交付對象」。計時器可用現成品控制課堂節奏；做計時器不等於完成這個工作挑戰。')),
('獨立做一次可追溯的修改',steps(['先保存舊版工具與資料。寫出正常答案、至少一項例外處理，以及需要修改的規則。','自己將變更交給 AI，保存 v2；先跑原資料確認沒有退步，再跑新資料核對預期差異。','若結果不同，記下實際現象，修正需求或生成結果，重跑受影響測試。例外輸入修好後，正常功能仍要可用。','輸出一份可分享成品、完整指令與驗收表，關閉後重新開啟再使用。'])+answer('預算遷移：估算 20,600；實支 21,300；較估算增加 700；核定餘額 3,700。例外仍須自行設計與實測，例如清空數量或核定不足。')),
('完課驗收：用證據確認',p('檢查五件成果：① 可重開的工具或 AI 專案；② 已知答案的輸入與實測結果；③ 一項有效需求變更及再測；④ 可閱讀的交付物；⑤ 保存完整指令與使用說明。說明一個工作判斷，例如超支、指標方向或未定期限。')+p('尚缺生成、模型呼叫或重開證據時，清楚記待完成。倒數結束、畫面漂亮與關鍵字分數都不替代驗收。確認各站完成證據後，回 <a href="../index.html#required-route">目錄成果清單</a>勾選；其他工具留待工作需要再探索。'))])

