trans=str.maketrans({'输入':'輸入'}) if False else str.maketrans('单显与给承担节终则时对设场档计为数','單顯與給承擔節終則時對設場檔計為數')
for f in [*F.glob('*.html'),*M.glob('prompt-*.txt')]:f.write_text(f.read_text().translate(trans))
source='# Gemini AI 必修教案與素材契約\n\n版本：2026-10-06；來源：已授權的 REVISION-PRINCIPLES.md。正式必修正文以下列 fragments 為準，HTML 修補前已凍結；平台帳號、模型生成與真人跟做待驗。\n\n學員：零程式、零 AI；成果：可重開工具、已知答案查核、需求變更再測、交付物與使用說明。主案例：預算、KPI、AI交辦。活動分工見 REPAIR-PLAN.md。\n\n'
for file,d in pages.items():
    source+=f'## {file} — {d["title"]}\n\n{d["tagline"]}\n\n學習成果：'+ '；'.join(d['outcomes'])+f'。\n\n正式正文：[完整 HTML 內容](fragments/{d["fragment"]})；材料與操作、結果、查核、修復均寫於正文。\n\n'
(ROOT/'_source/LESSON-PLANS.md').write_text(source.translate(trans))
(ROOT/'_source/lesson-map.json').write_text(json.dumps(pages,ensure_ascii=False,indent=2).translate(trans))
